package com.cvns.service;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.cvns.custom_exceptions.*;import com.cvns.dtos.RequestDtos.VaccineRequest;import com.cvns.dtos.ResponseDtos.VaccineResponse;import com.cvns.entities.Vaccine;import com.cvns.repository.VaccineRepository;import lombok.RequiredArgsConstructor;
@Service @Transactional(readOnly=true) @RequiredArgsConstructor public class VaccineService{private final VaccineRepository repo;public List<VaccineResponse> list(){return repo.findAllByOrderByDueAgeMonthsAscDoseNumberAsc().stream().map(DtoMapper::vaccine).toList();}@Transactional public VaccineResponse add(VaccineRequest r){if(repo.existsByNameAndDoseNumber(r.name(),r.doseNumber()))throw new ApiException("Vaccine dose already exists");Vaccine v=new Vaccine();set(v,r);return DtoMapper.vaccine(repo.save(v));}@Transactional public VaccineResponse update(Long id,VaccineRequest r){Vaccine v=entity(id);set(v,r);return DtoMapper.vaccine(v);}@Transactional public void delete(Long id){repo.delete(entity(id));}public Vaccine entity(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Vaccine not found"));}private void set(Vaccine v,VaccineRequest r){v.setName(r.name());v.setDescription(r.description());v.setDueAgeMonths(r.dueAgeMonths());v.setDoseNumber(r.doseNumber());}}
